<?php require 'common.php'; try{$in=body_json();$url=$in['url']??'';if(!$url)throw new Exception('Missing media URL.');$user=clean_user($in['username']??'unknown_user');$name=basename($in['filename']??filename_for($in));$root=dirname(__DIR__).'/downloads/'.$user;if(!is_dir($root))mkdir($root,0777,true);$path=$root.'/'.$name;$data=http_get($url,90);file_put_contents($path,$data);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$mime=$ext==='mp4'?'video/mp4':'image/jpeg';header('Content-Type: '.$mime);header('Content-Disposition: attachment; filename="'.basename($name).'"');header('Content-Length: '.strlen($data));echo $data;}catch(Throwable $e){send_json(['ok'=>false,'error'=>$e->getMessage()],500);}
